export const MATERIALS=[
 {id:'jade',name:'비취 광체',color:0x25e6a3,emissive:.65,mass:1},
 {id:'glass',name:'별빛 유리',color:0x7bc9ff,emissive:.3,mass:.7},
 {id:'gold',name:'태양 합금',color:0xffc25b,emissive:.25,mass:1.8},
 {id:'rose',name:'분홍 공명석',color:0xff75bd,emissive:.5,mass:1.1},
 {id:'stone',name:'현무암',color:0x607387,emissive:0,mass:2.5},
 {id:'white',name:'달빛 세라믹',color:0xe3f4ed,emissive:.05,mass:1.2}
];
export const ISLANDS=[{x:0,y:0,z:0,r:31},{x:-64,y:14,z:-38,r:21},{x:60,y:24,z:-52,r:18},{x:62,y:-9,z:40,r:26},{x:-48,y:30,z:58,r:15},{x:0,y:45,z:-110,r:25},{x:-108,y:-4,z:30,r:17},{x:100,y:50,z:80,r:16}];
export const TOOL_NAMES=['물질 프린터','중력 앵커','결정 씨앗','공명 파동','광자 연결선','회수 광선'];
export const finite=(x,def=0)=>Number.isFinite(x)?x:def;
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function rng(seed){let n=seed>>>0;return()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);
export class Forge {
 constructor(seed=8241,saved=null){this.uid=0;this.eid=0;this.random=rng(seed);this.undoStacks={};this.s={seed,time:0,timeOfDay:.68,gravity:1.8,weather:'clear',nodes:[],bonds:[],players:[],events:[],created:0,discoveries:[],orbitCount:0};if(saved&&Array.isArray(saved.nodes)){this.s={...this.s,...saved,players:[],events:[]};this.uid=Math.max(0,...this.s.nodes.map(n=>n.id));this.random=rng(this.s.seed);}else this.populate();}
 event(type,data={}){this.s.events.push({id:++this.eid,type,...data});if(this.s.events.length>45)this.s.events.shift();}
 populate(){const old=this.s.created;for(let i=0;i<9;i++){const a=i*Math.PI*2/9;this.create({kind:'matter',material:i%6,shape:i%3,x:Math.cos(a)*9,y:1.2,z:Math.sin(a)*9,locked:true,size:1.5});}this.create({kind:'core',x:0,y:8,z:-10,locked:true,size:2,polarity:1});for(let i=0;i<12;i++){const a=i*Math.PI/6;this.create({kind:'matter',material:i%4,shape:i%3,x:Math.cos(a)*6,y:8+Math.sin(a*2),z:-10+Math.sin(a)*6,size:.65,locked:false,vx:Math.sin(a)*3,vz:-Math.cos(a)*3});}for(const [i,is]of ISLANDS.entries()){if(i===0)continue;this.create({kind:'seed',x:is.x+2,y:is.y+.5,z:is.z,locked:true,size:.8,growth:20,age:50});this.growTree(is.x+2,is.y+.5,is.z,i);}this.s.created=old;}
 create(data){if(this.s.nodes.length>=650){const idx=this.s.nodes.findIndex(n=>n.kind==='matter'&&!n.locked);if(idx>=0)this.s.nodes.splice(idx,1);else return null;}const n={id:++this.uid,kind:'matter',material:0,shape:0,size:1,x:0,y:8,z:0,vx:0,vy:0,vz:0,rx:0,ry:0,rz:0,locked:false,age:0,...data};this.s.nodes.push(n);return n;}
 addPlayer(id,name='창조자',color=0){if(this.s.players.length>=4)return false;this.s.players.push({id,name:String(name).replace(/[<>\x00-\x1f]/g,'').slice(0,16)||'창조자',x:0,y:9,z:24,yaw:0,pitch:0,color,speed:12,fly:true,god:true,tool:0,material:0,actions:0});return true;}
 removePlayer(id){this.s.players=this.s.players.filter(p=>p.id!==id);delete this.undoStacks[id];}
 move(id,data,dt=.1){const p=this.s.players.find(p=>p.id===id);if(!p)return;const next={x:clamp(finite(data.x,p.x),-220,220),y:clamp(finite(data.y,p.y),-60,180),z:clamp(finite(data.z,p.z),-220,220)};if(distance(p,next)>Math.max(12,p.speed*dt*5))return;p.x=next.x;p.y=next.y;p.z=next.z;p.yaw=finite(data.yaw,p.yaw);p.pitch=clamp(finite(data.pitch,p.pitch),-1.55,1.55);p.tool=clamp(Math.floor(finite(data.tool)),0,5);p.material=clamp(Math.floor(finite(data.material)),0,5);}
 point(player,data){return{x:clamp(finite(data.x,player.x),-180,180),y:clamp(finite(data.y,player.y),-45,150),z:clamp(finite(data.z,player.z),-180,180)};}
 action(id,data){const p=this.s.players.find(p=>p.id===id);if(!p)return{ok:false,message:'파일럿을 찾을 수 없습니다.'};const pt=this.point(p,data);if(distance(p,pt)>45)return{ok:false,message:'45m 안의 공간을 선택하세요.'};const tool=clamp(Math.floor(finite(data.tool)),0,5),ids=[];
  if(tool===0){const n=this.create({...pt,material:clamp(Math.floor(finite(data.material)),0,5),shape:clamp(Math.floor(finite(data.shape)),0,2),size:clamp(finite(data.size,1),.4,3),locked:!!data.locked,vx:finite(data.vx),vy:finite(data.vy),vz:finite(data.vz)});if(n)ids.push(n.id);this.s.created++;this.event('create',{...pt,color:MATERIALS[clamp(Math.floor(finite(data.material)),0,5)].color});}
  if(tool===1){const n=this.create({...pt,kind:'core',locked:true,size:1.8,polarity:data.alternate?-1:1});if(n)ids.push(n.id);this.event('anchor',pt);this.discover('anchor','중력의 첫 문장');}
  if(tool===2){const n=this.create({...pt,kind:'seed',locked:true,size:.75,growth:0});if(n)ids.push(n.id);this.event('seed',pt);this.discover('seed','빛을 심는 사람');}
  if(tool===3){for(const n of this.s.nodes)if(n.kind==='matter'&&!n.locked){const d=distance(n,pt);if(d<24){const force=(1-d/24)*28,den=Math.max(1,d);n.vx+=(n.x-pt.x)/den*force;n.vy+=(n.y-pt.y)/den*force+force*.4;n.vz+=(n.z-pt.z)/den*force;}}this.event('pulse',pt);this.discover('pulse','공명의 파도');}
  if(tool===4){const target=this.s.nodes.find(n=>n.id===data.target);if(!target)return{ok:false,message:'물질을 조준해 첫 연결점을 선택하세요.'};if(!p.linkStart){p.linkStart=target.id;return{ok:true,message:'첫 연결점 선택됨 · 다른 물질을 클릭하세요.'};}const first=this.s.nodes.find(n=>n.id===p.linkStart);p.linkStart=null;if(first&&first.id!==target.id){this.s.bonds.push({a:first.id,b:target.id,length:Math.min(15,distance(first,target))});this.event('link',{...pt});this.discover('bond','빛으로 엮은 구조');return{ok:true,message:'광자 연결 완료 · 자유 물질은 탄성으로 연결됩니다.'};}}
  if(tool===5){const target=this.s.nodes.find(n=>n.id===data.target);if(target){if(data.alternate){target.locked=!target.locked;return{ok:true,message:target.locked?'물질을 공간에 고정했습니다.':'물질을 자유롭게 풀었습니다.'};}this.undoStacks[id]=[...(this.undoStacks[id]||[]),{removed:structuredClone(target)}].slice(-30);this.s.nodes=this.s.nodes.filter(n=>n.id!==target.id);this.s.bonds=this.s.bonds.filter(b=>b.a!==target.id&&b.b!==target.id);this.event('erase',{x:target.x,y:target.y,z:target.z});return{ok:true};}}
  if(ids.length)this.undoStacks[id]=[...(this.undoStacks[id]||[]),{ids}].slice(-30);p.actions++;if(this.s.created>=12)this.discover('matter','물질 연금술사');return{ok:true};
 }
 discover(id,title){if(this.s.discoveries.includes(id))return;this.s.discoveries.push(id);this.event('discovery',{title});}
 undo(id){const stack=this.undoStacks[id]||[],last=stack.pop();if(!last)return'되돌릴 작업이 없습니다.';if(last.removed)this.s.nodes.push(last.removed);if(last.ids){this.s.nodes=this.s.nodes.filter(n=>!last.ids.includes(n.id)&&!last.ids.includes(n.parent));this.s.bonds=this.s.bonds.filter(b=>!last.ids.includes(b.a)&&!last.ids.includes(b.b));}return'마지막 생성을 되돌렸습니다.';}
 growTree(x,y,z,index=0,parent=0,step=20){const rr=rng(Math.round(x*79+z*91+index*131));for(let i=0;i<Math.min(20,step);i++){const h=i*.36+1,a=i*2.399+index,rad=i<5?.2:1.3+Math.sin(i*.7)*.7;const n=this.create({kind:i<6?'branch':'crystal',x:x+Math.cos(a)*rad,y:y+h,z:z+Math.sin(a)*rad,material:i%3===0?3:0,shape:2,size:i<6?.4:.6+rr()*.6,locked:true,rx:rr()*.5,rz:rr()*.5,parent});if(!n)break;}}
 command(id,text){const p=this.s.players.find(p=>p.id===id);if(!p)return'신호가 없습니다.';const [cmd,...args]=String(text).trim().replace(/^\//,'').split(/\s+/);const n=(i,d)=>Number.isFinite(Number(args[i]))?Number(args[i]):d;
  if(cmd==='help')return'/give 비취|유리|금|분홍|돌|달빛 [수량] · /gravity 0~12 · /time day|night|sunset · /weather meteor|clear · /tp x y z · /speed 4~50 · /build ring|helix|bridge · /clear · /undo · /home · /seed · /fly · /god';
  if(cmd==='gravity'){this.s.gravity=clamp(n(0,1.8),0,12);return`세계 중력: ${this.s.gravity.toFixed(1)}`;}
  if(cmd==='time'){this.s.timeOfDay=args[0]==='night'?.72:args[0]==='sunset'?.45:.22;return`하늘 변경: ${args[0]||'day'}`;}
  if(cmd==='weather'){this.s.weather=args[0]==='meteor'?'meteor':'clear';return this.s.weather==='meteor'?'유성우가 시작됩니다.':'하늘이 맑아졌습니다.';}
  if(cmd==='tp'){if(args.length<3)return'사용법: /tp x y z';p.x=clamp(n(0,0),-180,180);p.y=clamp(n(1,10),-40,160);p.z=clamp(n(2,0),-180,180);this.event('teleport',{player:id,x:p.x,y:p.y,z:p.z});return'공간 좌표 이동 완료.';}
  if(cmd==='home'){p.x=0;p.y=9;p.z=24;this.event('teleport',{player:id,x:p.x,y:p.y,z:p.z});return'중앙 공방으로 돌아왔습니다.';}
  if(cmd==='speed'){p.speed=clamp(n(0,12),4,50);return`비행 속도 ${p.speed} m/s`;}
  if(cmd==='fly'){p.fly=!p.fly;return p.fly?'자유 비행 ON':'중력 비행 ON · Space로 상승할 수 있습니다.';}
  if(cmd==='god'){p.god=!p.god;return p.god?'안전 모드 ON':'안전 모드 OFF · 추락하면 공방으로 복귀합니다.';}
  if(cmd==='seed')return`세계 시드: ${this.s.seed}`;
  if(cmd==='undo')return this.undo(id);
  if(cmd==='clear'){this.s.nodes=this.s.nodes.filter(n=>n.locked);this.s.bonds=this.s.bonds.filter(b=>this.s.nodes.some(n=>n.id===b.a)&&this.s.nodes.some(n=>n.id===b.b));return'자유 물질을 모두 회수했습니다. 고정 구조물은 유지됩니다.';}
  if(cmd==='give'||cmd==='spawn'){const aliases={비취:0,유리:1,금:2,분홍:3,돌:4,달빛:5,jade:0,glass:1,gold:2,rose:3,stone:4,white:5};if(args[0]==='core'||args[0]==='seed'){this.action(id,{tool:args[0]==='core'?1:2,x:p.x,y:p.y,z:p.z-8});return'특수 장치를 생성했습니다.';}const count=clamp(Math.floor(n(1,12)),1,60),material=aliases[args[0]]??p.material;for(let i=0;i<count;i++)this.create({x:p.x+(this.random()-.5)*9,y:p.y+2+this.random()*5,z:p.z-8+(this.random()-.5)*9,material,shape:i%3,size:.5+this.random()*.7,vx:(this.random()-.5)*4,vy:this.random()*4,vz:(this.random()-.5)*4});this.s.created+=count;this.event('rain',{x:p.x,y:p.y,z:p.z-8});return`${MATERIALS[material].name} ${count}개 생성.`;}
  if(cmd==='build'){const ids=[];for(let i=0;i<36;i++){let x,y,z;if(args[0]==='bridge'){x=p.x+(i%3-1)*1.2;y=p.y-2;z=p.z-4-Math.floor(i/3)*1.2;}else if(args[0]==='helix'){const a=i*.55;x=p.x+Math.cos(a)*4;y=p.y-3+i*.35;z=p.z-10+Math.sin(a)*4;}else{const a=i*Math.PI/18;x=p.x+Math.cos(a)*6;y=p.y+Math.sin(a)*6;z=p.z-12;}const node=this.create({x,y,z,material:i%6,shape:args[0]==='bridge'?0:2,size:args[0]==='bridge'?1.15:.7,locked:true});if(node)ids.push(node.id);}this.undoStacks[id]=[...(this.undoStacks[id]||[]),{ids}].slice(-30);this.discover('build','생각을 세우는 건축가');return'청사진 구조물을 생성했습니다. /undo로 되돌릴 수 있습니다.';}
  if(cmd==='gamemode'){this.s.weather=args[0]==='chaos'?'meteor':'clear';this.s.gravity=args[0]==='chaos'?5:1.8;return args[0]==='chaos'?'카오스 실험 모드':'자유 창작 모드';}
  return'알 수 없는 명령입니다. /help로 공식 치트 목록을 확인하세요.';
 }
 step(dt){dt=clamp(dt,0,.05);const s=this.s;s.time+=dt;const cores=s.nodes.filter(n=>n.kind==='core');let orbit=0;
  for(const seed of [...s.nodes]){seed.age+=dt;if(seed.kind==='seed'&&(seed.growth||0)<20&&seed.age>(seed.growth||0)*.32){const i=seed.growth||0,a=i*2.399,rad=i<5?.2:1.3+Math.sin(i*.7)*.7;this.create({kind:i<6?'branch':'crystal',x:seed.x+Math.cos(a)*rad,y:seed.y+i*.36+1,z:seed.z+Math.sin(a)*rad,material:i%3===0?3:0,shape:2,size:i<6?.4:.8,locked:true,parent:seed.id});seed.growth=i+1;if(seed.growth===20)this.event('grown',{x:seed.x,y:seed.y+4,z:seed.z});}}
  const free=s.nodes.filter(n=>!n.locked);for(const n of free){let vy=-s.gravity;let anchored=false;for(const core of cores){const dx=n.x-core.x,dy=n.y-core.y,dz=n.z-core.z,d=Math.hypot(dx,dy,dz);if(d<26&&d>.2){const polarity=core.polarity||1;if(polarity===1){const f=clamp((d-7)*2,-12,35);n.vx+=(-dx/d*f-dz/d*4-n.vx*.32)*dt;n.vz+=(-dz/d*f+dx/d*4-n.vz*.32)*dt;n.vy+=(-dy*2-n.vy*.6)*dt;anchored=true;if(d<11)orbit++;}else{const f=(26-d)*1.7;n.vx+=dx/d*f*dt;n.vy+=dy/d*f*dt;n.vz+=dz/d*f*dt;}}}if(!anchored)n.vy+=vy*dt;const drag=Math.exp(-dt*.08);n.vx=clamp(n.vx*drag,-55,55);n.vy=clamp(n.vy*drag,-55,55);n.vz=clamp(n.vz*drag,-55,55);n.x+=n.vx*dt;n.y+=n.vy*dt;n.z+=n.vz*dt;n.rx+=n.vz*dt*.12;n.rz-=n.vx*dt*.12;n.ry+=dt*.1;
    const radius=n.size*.5;for(const is of ISLANDS)if((n.x-is.x)**2+(n.z-is.z)**2<(is.r-1)**2&&n.y-radius<is.y+.15&&n.y-radius>is.y-3&&n.vy<0){n.y=is.y+.15+radius;n.vy=-n.vy*.42;if(Math.abs(n.vy)<.4)n.vy=0;n.vx*=Math.exp(-dt*2);n.vz*=Math.exp(-dt*2);}
    if(n.y< -65){n.y=80;n.vy=0;n.x=clamp(n.x,-140,140);n.z=clamp(n.z,-140,140);}
  }
  const map=new Map(s.nodes.map(n=>[n.id,n]));for(const b of s.bonds){const a=map.get(b.a),n=map.get(b.b);if(!a||!n)continue;const dx=n.x-a.x,dy=n.y-a.y,dz=n.z-a.z,d=Math.hypot(dx,dy,dz)||1,f=clamp((d-b.length)*3,-25,25);if(!a.locked){a.vx+=dx/d*f*dt;a.vy+=dy/d*f*dt;a.vz+=dz/d*f*dt;}if(!n.locked){n.vx-=dx/d*f*dt;n.vy-=dy/d*f*dt;n.vz-=dz/d*f*dt;}}
  // Spatial buckets keep collision work bounded as experiments become dense.
  const buckets=new Map();for(const n of s.nodes){if(n.kind!=='matter')continue;const key=`${Math.floor(n.x/4)},${Math.floor(n.y/4)},${Math.floor(n.z/4)}`;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(n);}for(const a of free){if(a.kind!=='matter')continue;const x=Math.floor(a.x/4),y=Math.floor(a.y/4),z=Math.floor(a.z/4);for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++)for(let k=-1;k<=1;k++)for(const b of buckets.get(`${x+i},${y+j},${z+k}`)||[]){if(a.id>=b.id&&!b.locked||a.id===b.id)continue;const dx=a.x-b.x,dy=a.y-b.y,dz=a.z-b.z,d=Math.hypot(dx,dy,dz)||.001,r=(a.size+b.size)*.48;if(d<r){const correction=(r-d)*(b.locked?1:.5);a.x+=dx/d*correction;a.y+=dy/d*correction;a.z+=dz/d*correction;const rel=(a.vx-b.vx)*dx/d+(a.vy-b.vy)*dy/d+(a.vz-b.vz)*dz/d;if(rel<0){const impulse=-rel*.65;a.vx+=dx/d*impulse;a.vy+=dy/d*impulse;a.vz+=dz/d*impulse;if(!b.locked){b.x-=dx/d*correction;b.y-=dy/d*correction;b.z-=dz/d*correction;b.vx-=dx/d*impulse;b.vy-=dy/d*impulse;b.vz-=dz/d*impulse;}}}}}
  s.orbitCount=orbit;if(orbit>=8)this.discover('orbit','작은 우주의 설계자');
  if(s.weather==='meteor'&&this.random()<dt*2&&s.nodes.length<620){this.create({x:(this.random()-.5)*140,y:75,z:(this.random()-.5)*140,material:2,shape:2,size:1+this.random()*1.5,vx:8,vy:-12,vz:4});}
 }
 save(){return{...this.s,players:[],events:[]};}
}
